class ModelColumnView final : public QColumnView {
 public:
  explicit ModelColumnView(QWidget *parent = nullptr) : QColumnView(parent) {}

  qt6cr_void_callback_t current_index_changed_callback = nullptr;
  void *current_index_changed_userdata = nullptr;
  qt6cr_handle_callback_t update_preview_widget_callback = nullptr;
  void *update_preview_widget_userdata = nullptr;
  QMetaObject::Connection update_preview_widget_connection;
  bool preview_column_visible = true;
  QPointer<QWidget> logical_preview_widget;
  QPointer<QWidget> placeholder_preview_widget;

  void setModel(QAbstractItemModel *model) override {
    if (current_changed_connection) {
      QObject::disconnect(current_changed_connection);
    }

    QColumnView::setModel(model);
    reconnect_current_changed();
  }

  void setSelectionModel(QItemSelectionModel *selection_model) override {
    if (current_changed_connection) {
      QObject::disconnect(current_changed_connection);
    }

    QColumnView::setSelectionModel(selection_model);
    reconnect_current_changed();
  }

  void reconnect_current_changed() {
    auto *selection_model = selectionModel();

    if (selection_model == nullptr || current_index_changed_callback == nullptr) {
      return;
    }

    current_changed_connection = QObject::connect(selection_model, &QItemSelectionModel::currentChanged, this, [this](const QModelIndex &, const QModelIndex &) {
      if (current_index_changed_callback != nullptr) {
        current_index_changed_callback(current_index_changed_userdata);
      }
    });
  }

  void reconnect_update_preview_widget() {
    if (update_preview_widget_connection) {
      QObject::disconnect(update_preview_widget_connection);
    }

    if (update_preview_widget_callback == nullptr) {
      return;
    }

    update_preview_widget_connection = QObject::connect(this, &QColumnView::updatePreviewWidget, this, [this](const QModelIndex &index) {
      if (update_preview_widget_callback != nullptr) {
        update_preview_widget_callback(update_preview_widget_userdata, new QModelIndex(index));
      }
    });
  }

  bool isPreviewColumnVisible() const {
    return preview_column_visible;
  }

  void setPreviewColumnVisible(bool value) {
    preview_column_visible = value;

    if (auto *widget = previewWidget()) {
      widget->setVisible(value);
    }
  }

  QWidget *previewWidget() const {
    return logical_preview_widget.data();
  }

  void setPreviewWidget(QWidget *widget) {
    logical_preview_widget = widget;

    if (widget == nullptr) {
      if (placeholder_preview_widget == nullptr) {
        placeholder_preview_widget = new QWidget(this);
        placeholder_preview_widget->hide();
      }

      QColumnView::setPreviewWidget(placeholder_preview_widget);
      return;
    }

    QColumnView::setPreviewWidget(widget);
    widget->setVisible(preview_column_visible);
  }

 private:
  QMetaObject::Connection current_changed_connection;
};

