QMimeData *clone_mime_data(const QMimeData *source) {
  if (source == nullptr) {
    return nullptr;
  }

  auto *copy = new QMimeData();

  if (source->hasText()) {
    copy->setText(source->text());
  }

  for (const auto &format : source->formats()) {
    copy->setData(format, source->data(format));
  }

  return copy;
}

