qt6cr_pointf_t to_pointf(const QPointF &point) {
  return qt6cr_pointf_t{point.x(), point.y()};
}

qt6cr_pointf_t to_pointf(const QPoint &point) {
  return qt6cr_pointf_t{static_cast<double>(point.x()), static_cast<double>(point.y())};
}

qt6cr_point_t to_point(const QPoint &point) {
  return qt6cr_point_t{point.x(), point.y()};
}

qt6cr_vector3d_t to_vector3d(const QVector3D &vector) {
  return qt6cr_vector3d_t{vector.x(), vector.y(), vector.z()};
}

qt6cr_matrix4x4_t to_matrix4x4(const QMatrix4x4 &matrix) {
  return qt6cr_matrix4x4_t{
      matrix(0, 0), matrix(0, 1), matrix(0, 2), matrix(0, 3),
      matrix(1, 0), matrix(1, 1), matrix(1, 2), matrix(1, 3),
      matrix(2, 0), matrix(2, 1), matrix(2, 2), matrix(2, 3),
      matrix(3, 0), matrix(3, 1), matrix(3, 2), matrix(3, 3)};
}

qt6cr_linef_t to_linef(const QLineF &line) {
  return qt6cr_linef_t{line.x1(), line.y1(), line.x2(), line.y2()};
}

qt6cr_gradient_stop_t to_gradient_stop(const QGradientStop &stop) {
  return qt6cr_gradient_stop_t{stop.first, to_color(stop.second)};
}

qt6cr_table_widget_selection_range_t to_table_widget_selection_range(const QTableWidgetSelectionRange &range) {
  return qt6cr_table_widget_selection_range_t{
      range.topRow(),
      range.leftColumn(),
      range.bottomRow(),
      range.rightColumn()};
}

QTableWidgetSelectionRange from_table_widget_selection_range(qt6cr_table_widget_selection_range_t range) {
  return QTableWidgetSelectionRange(range.top_row, range.left_column, range.bottom_row, range.right_column);
}

