  if (icon == nullptr || target == nullptr) {
    return;
  }

  icon->paint(
    target,
    x,
    y,
    width,
    height,
    static_cast<Qt::Alignment>(alignment),
    static_cast<QIcon::Mode>(mode),
    static_cast<QIcon::State>(state)
  );
