int qt6cr_graphics_layout_kind(qt6cr_handle_t handle) {
  auto *layout = as_graphics_layout(handle);

  if (dynamic_cast<QGraphicsAnchorLayout *>(layout) != nullptr) {
    return 1;
  }

  if (dynamic_cast<QGraphicsGridLayout *>(layout) != nullptr) {
    return 2;
  }

  if (dynamic_cast<QGraphicsLinearLayout *>(layout) != nullptr) {
    return 3;
  }

  return 0;
}

int qt6cr_graphics_layout_item_kind(qt6cr_handle_t handle) {
  auto *item = as_graphics_layout_item(handle);

  if (dynamic_cast<QGraphicsAnchorLayout *>(item) != nullptr) {
    return 1;
  }

  if (dynamic_cast<QGraphicsGridLayout *>(item) != nullptr) {
    return 2;
  }

  if (dynamic_cast<QGraphicsLinearLayout *>(item) != nullptr) {
    return 3;
  }

  if (dynamic_cast<QGraphicsWidget *>(item) != nullptr) {
    return 4;
  }

  return 0;
}

